#include <stdio.h>
#include <stdlib.h>
#include <ascauth.h>

int main(int argc, char *argv[])
{
    ASCENV *asce;
    char buffer[2000];
    int rc;
    char *user;

    if (argc != 2) {
        fprintf(stderr, "usage: %s <user>\n", argv[0]);
        exit(EXIT_FAILURE);
    }
    user = argv[1];

    /* Initialize the authentication environment */
    asce = ASC_INIT(NULL);
    if (asce == NULL) {
        fprintf(stderr, "Error: cannot initialize authentication environment\n");
        exit(EXIT_FAILURE);
    }

    /* Retrieve security equivalence list */
    rc = ASC_LISTSEQV(asce, user, buffer, sizeof(buffer));
    if (rc == AS_OK) {
        printf("Security equivalences of user %s:\n%s\n", user, buffer);
    } else if (rc == AS_TOOSMALL) {
        printf("Security equivalences of user %s (truncated):\n%s\n", user, buffer);
        printf("** list was truncated because of lack of buffer space **\n");
    } else {
        printf("RC=%d, %s\n", rc, ASC_STRERROR(rc));
    }

    /* Terminate the authentication environment */
    ASC_TERM(asce);
    return 0;
}
